-- Additive audit for normal Google Play cloud saves. Server time only.
-- Records are independent of clan/rank points and never impose sanctions.
CREATE TABLE IF NOT EXISTS level_history (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL,
 source TEXT NOT NULL CHECK(source IN ('baseline','created','change')),
 old_level INTEGER,new_level INTEGER,
 old_xp INTEGER,new_xp INTEGER,
 old_value TEXT,new_value TEXT,
 previous_save_at INTEGER,observed_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS level_history_player ON level_history(player_id,id DESC);
CREATE TRIGGER IF NOT EXISTS level_history_created AFTER INSERT ON player_saves
WHEN EXISTS(SELECT 1 FROM players WHERE id=NEW.player_id)
BEGIN
 INSERT INTO level_history(player_id,revision,source,old_level,new_level,old_xp,new_xp,old_value,new_value,previous_save_at,observed_at) VALUES(NEW.player_id,NEW.revision,'created',NULL,CASE WHEN json_type((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level')='integer' AND json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level') BETWEEN 1 AND 10000 THEN CAST(json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level') AS INTEGER) ELSE NULL END,NULL,CASE WHEN json_type((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.xp') IN ('integer','real') AND json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.xp') BETWEEN 0 AND 9007199254740991 THEN CAST(json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.xp') AS INTEGER) ELSE 0 END,NULL,COALESCE(substr(CAST(json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level') AS TEXT),1,80),'ausente'),NULL,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER));
END;
CREATE TRIGGER IF NOT EXISTS level_history_changed AFTER UPDATE OF payload ON player_saves
WHEN EXISTS(SELECT 1 FROM players WHERE id=NEW.player_id) AND ((json_type((CASE WHEN json_valid(OLD.payload) THEN OLD.payload ELSE '{}' END),'$.level') IS NOT json_type((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level')) OR (COALESCE(substr(CAST(json_extract((CASE WHEN json_valid(OLD.payload) THEN OLD.payload ELSE '{}' END),'$.level') AS TEXT),1,80),'ausente') IS NOT COALESCE(substr(CAST(json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level') AS TEXT),1,80),'ausente')))
BEGIN
 INSERT INTO level_history(player_id,revision,source,old_level,new_level,old_xp,new_xp,old_value,new_value,previous_save_at,observed_at) VALUES(NEW.player_id,NEW.revision,'change',CASE WHEN json_type((CASE WHEN json_valid(OLD.payload) THEN OLD.payload ELSE '{}' END),'$.level')='integer' AND json_extract((CASE WHEN json_valid(OLD.payload) THEN OLD.payload ELSE '{}' END),'$.level') BETWEEN 1 AND 10000 THEN CAST(json_extract((CASE WHEN json_valid(OLD.payload) THEN OLD.payload ELSE '{}' END),'$.level') AS INTEGER) ELSE NULL END,CASE WHEN json_type((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level')='integer' AND json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level') BETWEEN 1 AND 10000 THEN CAST(json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level') AS INTEGER) ELSE NULL END,CASE WHEN json_type((CASE WHEN json_valid(OLD.payload) THEN OLD.payload ELSE '{}' END),'$.xp') IN ('integer','real') AND json_extract((CASE WHEN json_valid(OLD.payload) THEN OLD.payload ELSE '{}' END),'$.xp') BETWEEN 0 AND 9007199254740991 THEN CAST(json_extract((CASE WHEN json_valid(OLD.payload) THEN OLD.payload ELSE '{}' END),'$.xp') AS INTEGER) ELSE 0 END,CASE WHEN json_type((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.xp') IN ('integer','real') AND json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.xp') BETWEEN 0 AND 9007199254740991 THEN CAST(json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.xp') AS INTEGER) ELSE 0 END,COALESCE(substr(CAST(json_extract((CASE WHEN json_valid(OLD.payload) THEN OLD.payload ELSE '{}' END),'$.level') AS TEXT),1,80),'ausente'),COALESCE(substr(CAST(json_extract((CASE WHEN json_valid(NEW.payload) THEN NEW.payload ELSE '{}' END),'$.level') AS TEXT),1,80),'ausente'),CAST((julianday(OLD.updated_at)-2440587.5)*86400000 AS INTEGER),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER));
END;
-- Existing saves establish a starting point; they are not invented past history.
INSERT INTO level_history(player_id,revision,source,old_level,new_level,old_xp,new_xp,old_value,new_value,previous_save_at,observed_at)
 SELECT s.player_id,s.revision,'baseline',NULL,CASE WHEN json_type((CASE WHEN json_valid(s.payload) THEN s.payload ELSE '{}' END),'$.level')='integer' AND json_extract((CASE WHEN json_valid(s.payload) THEN s.payload ELSE '{}' END),'$.level') BETWEEN 1 AND 10000 THEN CAST(json_extract((CASE WHEN json_valid(s.payload) THEN s.payload ELSE '{}' END),'$.level') AS INTEGER) ELSE NULL END,NULL,CASE WHEN json_type((CASE WHEN json_valid(s.payload) THEN s.payload ELSE '{}' END),'$.xp') IN ('integer','real') AND json_extract((CASE WHEN json_valid(s.payload) THEN s.payload ELSE '{}' END),'$.xp') BETWEEN 0 AND 9007199254740991 THEN CAST(json_extract((CASE WHEN json_valid(s.payload) THEN s.payload ELSE '{}' END),'$.xp') AS INTEGER) ELSE 0 END,NULL,COALESCE(substr(CAST(json_extract((CASE WHEN json_valid(s.payload) THEN s.payload ELSE '{}' END),'$.level') AS TEXT),1,80),'ausente'),NULL,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)
 FROM player_saves s JOIN players p ON p.id=s.player_id
 WHERE NOT EXISTS(SELECT 1 FROM level_history h WHERE h.player_id=s.player_id);
